package com._8x8.herd.device_logs.contract;

import java.util.Optional;

/**
 * The kinds of file phones upload. Each suffix is what follows {@code <mac>-} in a file name.
 */
public enum FileType {
    APP_LOG("app.log", true),
    BOOT_LOG("boot.log", true),
    CALLS_XML("calls.xml", false);

    private final String suffix;
    private final boolean manualAllowed;

    FileType(String suffix, boolean manualAllowed) {
        this.suffix = suffix;
        this.manualAllowed = manualAllowed;
    }

    /**
     * The type whose suffix is exactly {@code suffix}, case included.
     */
    public static Optional<FileType> fromSuffix(String suffix) {
        for (FileType type : values()) {
            if (type.suffix.equals(suffix)) {
                return Optional.of(type);
            }
        }
        return Optional.empty();
    }

    public String suffix() {
        return suffix;
    }

    /**
     * Whether a phone can also send this type as a manual {@code <mac>-now-} upload.
     */
    public boolean manualAllowed() {
        return manualAllowed;
    }
}

